(1, 'Producto', 'fa-boxes', 'Modulo de gestion de productos para poder gestionar todo el catalogo de productos de un negocio.', 'productos', '[\"products_module\\/2020_02_03_223938_products.php\"]', '[]', '{\"productos_gestion\":\"Gestionar productos\",\"productos_obtener\":\"Obtener productos\",\"productos_modificar_stock\":\"Modificar el stock de productos\",\"crear_productos_nueva_venta\":\"Crear productos desde nueva venta\"}', '[]', '[{\"name\":\"Gestor de Inventario\",\"keyname\":\"gestor_de_inventario\",\"permisos\":[\"productos_gestion\",\"productos_obtener\"]}]', '0.1', NULL, NULL),
(2, 'Ventas', 'fa-shopping-cart', 'Modulo de gestion de ventas que permitira crear ventas y enlistar las ventas ya creadas en base a los productos.', 'ventas', '[\"sells_module\\/2020_02_03_222657_sells.php\",\"sells_module\\/2020_02_03_224657_products_sells.php\"]', '[\'productos\']', '{\"crear_venta\":\"Crear ventas\",\"gestionar_ventas\":\"Gestionar ventas\",\"gestionar_reportes\":\"Gestionar reportes\",\"obtener_venta\":\"Obtener ultima venta\",\"eliminar_venta\":\"Eliminar una venta\",\"getionar_tickets\":\"Gestionar tickets\",\"precio_unitario\":\"Modificar precio unitario\",\"gestionar_gastos\":\"Crear y eliminar gastos\"}', '{\"stgg_header\":{\"label\":\"Cabecera de recibo\",\"type\":\"string\",\"default\":\"COMERCIALIZADORA ARRIAGADA&ARRIAGADA SPA\"},\"stgg_casa_matriz\":{\"label\":\"Casa Matriz\",\"type\":\"string\"},\"stgg_contacto\":{\"label\":\"Contacto\",\"type\":\"string\"},\"stgg_horario\":{\"label\":\"Horario\",\"type\":\"string\"},\"stgg_url\":{\"label\":\"URL de web\",\"type\":\"string\"},\"stgg_mensaje_gracias\":{\"label\":\"Mensaje de agradecimiento en recibo\",\"type\":\"string\",\"default\":\"GRACIAS POR SU PREFERENCIA * TE ESPERAMOS NUEVAMENTE *\"},\"settings_printer\":{\"label\":\"Configuracion de la impresora\",\"type\":\"string\",\"default\":\"{\\\"win32\\\":[\\\"-print-settings noscale\\\"]}\"},\"settings_printer_method\":{\"label\":\"Metodo de impresion\",\"type\":\"string\",\"default\":\"default\"}}', '[{\"name\":\"Cajero\",\"keyname\":\"cajero\",\"permisos\":[\"obtener_mesas\",\"obtener_meseros\",\"crear_venta\",\"getionar_tickets\",\"gestionar_ventas\",\"productos_obtener\"]},{\"name\":\"Analista de Ventas\",\"keyname\":\"analista_de_ventas\",\"permisos\":[\"gestionar_ventas\",\"gestionar_reportes\"]},{\"name\":\"Tickero\",\"keyname\":\"tickero\",\"permisos\":[\"getionar_tickets\",\"productos_obtener\"]}]', '0.1', NULL, NULL),
(3, 'Cafetería', 'fa-store-alt', 'Modulo de cafeteria, contiene un control de mesas y meseros pudiendo de esta formar emular un restaurante virtual.', 'cafeteria', '[\"cafeteria_module\\/waiters\\/2021_01_07_113754_waiters_table.php\",\"cafeteria_module\\/boards\\/2021_01_07_113907_boards_table.php\"]', '[\'productos\', \'ventas\']', '{\"gestionar_meseros\":\"Gestion de meseros\",\"gestionar_mesas\":\"Gestion de mesas\",\"obtener_meseros\":\"Obtener meseros\",\"obtener_mesas\":\"Obtener mesas\"}', '{\"stgg_password_remove_product_ticket\":{\"label\":\"Contrase\\u00f1a para eliminar producto de un ticket\",\"type\":\"string\",\"default\":\"admin123456\"},\"settings_printer\":{\"label\":\"Configuracion de la impresora\",\"type\":\"string\",\"default\":\"{\\\"win32\\\":[\\\"-print-settings noscale\\\"]}\"},\"settings_printer_method\":{\"label\":\"Metodo de impresion\",\"type\":\"string\",\"default\":\"default\"},\"name_panel_tickets\":{\"label\":\"Nombre del panel de cafeteria\",\"type\":\"string\",\"default\":\"Cafeteria\"}}', '[]', '0.1', NULL, NULL),
(4, 'Ordenes de clientes', 'fa-store-alt', 'Modulo de ordenes de clientes, (requiere tambien el modulo de clientes!).', 'client_orders', '[\"client_orders_module\\/2021_09_22_000156_create_client_orders_table.php\"]', '[\'productos\', \'ventas\']', '{\"create_client_order\":\"Crear orden de cliente\",\"update_client_order\":\"Editar orden de cliente\",\"retrieve_client_orders\":\"Obtener ordenes de clientes\"}', '{\"name_shop_public_orders\":{\"label\":\"Nombre publico de app en orden\",\"type\":\"string\",\"default\":\"Nombre de tienda\"}}', '[{\"name\":\"Atencion al cliente\",\"keyname\":\"client_attentioner\",\"permisos\":[\"create_client_order\",\"update_client_order\",\"retrieve_client_orders\"]}]', '0.1', NULL, NULL),
(5, 'Historial de movimientos', 'fa-store-alt', 'Modulo de historial de movimientos.', 'historial_movimi', '[\"historical_module\\/2021_10_04_000615_create_history_movements_table.php\"]', '[]', '{\"can_see_historial\":\"Permitir ver historial de movimientos\"}', '[]', '[]', '0.1', NULL, NULL);
